//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLMXL.
package musicxml
import ("archive/zip"; "bytes"; "encoding/json"; "fmt"; "math/rand"; "os"; "path/filepath"; "testing")
func TestCodexMusicXMLMXL(t *testing.T) {
 root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(235781));samples:=[][]byte{[]byte("<score-partwise />"),[]byte("<x/>"),[]byte("PK\x03\x04bad")};for _,name:=range []string{"ode_to_joy.mxl","ode_to_joy.musicxml","twinkle_timewise.musicxml","minuet.musicxml"}{b,e:=os.ReadFile(filepath.Join("testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)}
 containers:=[]string{`<container><rootfile full-path="score.xml" media-type="application/vnd.recordare.musicxml+xml"/></container>`,`<container><rootfile full-path="score.xml"/></container>`,`<container><rootfile full-path="./score.xml" media-type="application/vnd.recordare.musicxml+xml"/></container>`,`<container><rootfile full-path="missing.xml"/><rootfile full-path="score.xml"/></container>`,`<container><rootfile full-path="score.xml" media-type="other"/></container>`,`<container><rootfile full-path="score.xml"/></container`,`<container/>`,`<rootfile full-path="score.xml"/>`,`<x:rootfile xmlns:x="urn:x" full-path="score.xml"/>`,`<container><rootfile full-path="score.xml"/></container><bad>`,`<x:rootfile full-path="score.xml"/>`,`<container><rootfile full-path="score&#46;xml"/></container>`,`<container><rootfile full-path="score.xml"/></container>&unknown;`,`<container><rootfile full-path="score.xml"/></bad>`,`<container><rootfile full-path="score.xml" /></container>trail`}
 scores:=[]string{"<score-partwise />","<score-timewise />","<x/>","garbage","<?xml version='1.0'?><score-partwise/>"}
 for i:=0;i<500;i++ {var b bytes.Buffer;w:=zip.NewWriter(&b);add:=func(name string,data []byte,method uint16) {f,e:=w.CreateHeader(&zip.FileHeader{Name:name,Method:method});if e!=nil{t.Fatal(e)};if _,e=f.Write(data);e!=nil{t.Fatal(e)}};if i%9==0{add("mimetype",[]byte("application/vnd.recordare.musicxml"),zip.Store)};if i%7!=0{add("META-INF/container.xml",[]byte(containers[r.Intn(len(containers))]),uint16(8*(i%2)))};for j:=0;j<1+r.Intn(3);j++{name:=[]string{"score.xml","other.musicxml","folder/../score.xml","META-INF/ignored.xml","notes.txt"}[r.Intn(5)];add(name,[]byte(scores[r.Intn(len(scores))]),uint16(8*r.Intn(2)))};if e:=w.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))}
 for i:=0;i<30;i++ {var buf bytes.Buffer;w:=zip.NewWriter(&buf);f,e:=w.Create("META-INF/container.xml");if e!=nil{t.Fatal(e)};f.Write([]byte(`<container><rootfile full-path="score.xml"/></container>`));f,e=w.CreateHeader(&zip.FileHeader{Name:"score.xml",Method:uint16(8*(i%2))});if e!=nil{t.Fatal(e)};f.Write(append([]byte("<score-partwise>"),bytes.Repeat([]byte("x"),i*50)...));if e=w.Close();e!=nil{t.Fatal(e)};raw:=buf.Bytes();samples=append(samples,append([]byte{},raw...));b:=append([]byte{},raw...);at:=bytes.Index(b,[]byte("score.xml"));_ = at;for p:=0;p+46<len(b);p++ {if bytes.Equal(b[p:p+4],[]byte{'P','K',1,2}) && p+46+9<=len(b) && string(b[p+46:p+55])=="score.xml" {b[p+16]^=0x80;break}};samples=append(samples,b)}
 out:=[]any{};for _,data:=range samples {head:=data[:min(len(data),1024)];detect:=Detect(head,bytes.NewReader(data),int64(len(data)));got,e:=readInput(bytes.NewReader(data),int64(len(data)));err:="";if e!=nil{err=fmt.Sprint(e)};out=append(out,map[string]any{"input":data,"want":[]any{detect,got,err}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/mxl.json"),b,0644);e!=nil{t.Fatal(e)}
}
